func (u *TaggingUpsertBulk) UpdateContext() *TaggingUpsertBulk {
	return u.Update(func(s *TaggingUpsert) {
		s.UpdateContext()
	})
}

// ClearContext clears the value of the "context" field.
func (u *TaggingUpsertBulk) ClearContext() *TaggingUpsertBulk {
	return u.Update(func(s *TaggingUpsert) {
		s.ClearContext()
	})
}

// Exec executes the query.
func (u *TaggingUpsertBulk) Exec(ctx context.Context) error {
	if u.create.err != nil {
		return u.create.err
	}
	for i, b := range u.create.builders {
		if len(b.conflict) != 0 {
			return fmt.Errorf("ent: OnConflict was set for builder %d. Set it on the TaggingCreateBulk instead", i)
		}
	}
	if len(u.create.conflict) == 0 {
		return errors.New("ent: missing options for TaggingCreateBulk.OnConflict")
	}
	return u.create.Exec(ctx)
}

// ExecX is like Exec, but panics if an error occurs.
func (u *TaggingUpsertBulk) ExecX(ctx context.Context) {
	if err := u.create.Exec(ctx); err != nil {
		panic(err)
	}
}
